// Log the conversation for analytics and follow-up
const data = $input.first().json;

const conversationLog = {
  id: `call-${Date.now()}`,
  timestamp: new Date().toISOString(),
  businessName: data.businessConfig?.businessName || 'Unknown',
  callerInfo: data.callerInfo || {},
  conversationSummary: data.output || '',
  actions: data.actions || [],
  duration: data.duration || 0,
  outcome: data.outcome || 'completed',
  followUpRequired: data.followUpRequired || false,
  appointmentBooked: data.appointmentBooked || false,
  transferRequested: data.transferRequested || false
};

return {
  json: {
    ...data,
    conversationLog
  }
};

